using Kaizen.Infrastructure.Persistence;using Kaizen.Domain.Entities;using Kaizen.Web.Services;using Kaizen.Domain.Rules;using Microsoft.Data.Sqlite;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Diagnostics;
namespace Kaizen.Tests;
public class ReviewRollbackTests
{
 private sealed class FailSecondSave:SaveChangesInterceptor{private int calls;public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData eventData,InterceptionResult<int> result,CancellationToken cancellationToken=default){calls++;if(calls==2)throw new InvalidOperationException("Falla simulada");return base.SavingChangesAsync(eventData,result,cancellationToken);}}
 [Fact]public async Task Failed_adjustment_rolls_back_review_versions_and_history(){await using var connection=new SqliteConnection("Data Source=:memory:");await connection.OpenAsync();var seedOptions=new DbContextOptionsBuilder<ApplicationDbContext>().UseSqlite(connection).Options;await using(var seed=new ApplicationDbContext(seedOptions)){await seed.Database.EnsureCreatedAsync();var start=new DateOnly(2026,8,1);var goal=new Meta{Titulo="Meta",Descripcion="D",PorQueEsImportante="I",SituacionActual="C",ResultadoEsperado="E",MetricaProgreso="M",AreaPersonal=new(){Nombre="Área"},FechaInicio=start,Estado=EstadoMeta.Activa};var action=new AccionPlanificada{Meta=goal,Nombre="Caminar",FechaInicio=start,VigenteDesde=start,Frecuencia=FrecuenciaAccion.Diaria,Estado=EstadoAccion.Activa};seed.Add(new AccionProgramada{AccionPlanificada=action,FechaProgramada=start,Estado=EstadoCumplimiento.Completada});await seed.SaveChangesAsync();}var failingOptions=new DbContextOptionsBuilder<ApplicationDbContext>().UseSqlite(connection).AddInterceptors(new FailSecondSave()).Options;await using(var db=new ApplicationDbContext(failingOptions)){var service=new ReviewService(db,new(db));var vm=(await service.BuildAsync(1,new(2026,8,1)))!;vm.QueFunciono="W";vm.QueDificulto="H";vm.Aprendizaje="L";vm.CambioProximoPeriodo="N";vm.Decisions[0].Tipo=TipoAjuste.Aumentar;vm.Decisions[0].Motivo="R";await Assert.ThrowsAsync<InvalidOperationException>(()=>service.SaveAsync(vm,default));}await using(var verify=new ApplicationDbContext(seedOptions)){Assert.Empty(verify.RevisionesKaizen);Assert.Empty(verify.AjustesPlan);Assert.Empty(verify.EventosHistorialMeta);Assert.Single(verify.AccionesPlanificadas);Assert.Equal(EstadoAccion.Activa,(await verify.AccionesPlanificadas.SingleAsync()).Estado);}}
}
